solution.solution.cpp:
double average(int total, int count)
{
    return static_cast<double>(total) / count;
}

unitTests:
TEST("seven over two") { CHECK_NEAR(average(7, 2), 3.5, 1e-9); }
TEST("divides evenly") { CHECK_NEAR(average(10, 5), 2.0, 1e-9); }
TEST("one third") { CHECK_NEAR(average(1, 3), 0.333333333, 1e-6); }

